module.exports = "<ng-template #chatContent>\n  <section class=\"bmb_chat-card\">\n    <bmb-home-card\n      [leftIcon]=\"mode() === 'chat' ? undefined : leftIcon()\"\n      [title]=\"title() || ('home_card_chat.title' | translate)\"\n      [subtitle]=\"subtitle() || ('home_card_chat.subtitle' | translate)\"\n      [icon]=\"icon()\"\n      [isMobile]=\"isMobile()\"\n      (onClose)=\"handleClose()\"\n      [actionHeaders]=\"chatActionHeaders()\"\n      [actionsList]=\"actionsList()\"\n      [isChat]=\"mode() === 'chat'\"\n      (onBack)=\"handleBack()\"\n      [bgIconAppearance]=\"bgIconAppearance()\"\n      [contentPadding]=\"'xs'\"\n      [isExpanded]=\"true\"\n    >\n      <div class=\"bmb_chat-card-container\">\n        @for (message of messagesHistory(); track $index) {\n          <bmb-chat-bubble [message]=\"message\" />\n        }\n      </div>\n      <div class=\"bmb_chat-card-chatBar\">\n        <bmb-chat-bar\n          [placeholder]=\"placeholder()\"\n          [botList]=\"botList()\"\n          [(currentBot)]=\"currentBot\"\n          [(isLoading)]=\"isLoading\"\n          (onSendMessage)=\"handleSend($event)\"\n        ></bmb-chat-bar>\n      </div>\n    </bmb-home-card>\n  </section>\n</ng-template>\n\n@if (mode() === 'expanded') {\n  <ng-container *ngTemplateOutlet=\"chatContent\"></ng-container>\n}\n\n<ng-template #contentTemplate>\n  <div class=\"bmb_chat-card-chat-content\">\n    <ng-container *ngTemplateOutlet=\"chatContent\"></ng-container>\n  </div>\n</ng-template>\n\n@if (mode() === 'compact') {\n  <bmb-action-icon\n    class=\"bmb_chat-card-bot\"\n    [icon]=\"currentBot()?.icon!\"\n    [alt]=\"currentBot()?.name!\"\n    [iconSize]=\"40\"\n    [isSVGTemplate]=\"true\"\n    (buttonClick)=\"openChatFromCompact()\"\n  >\n    <ng-template #customActionIcon>\n      <bmb-bot-icon [iconName]=\"currentBot()?.icon!\" />\n    </ng-template>\n  </bmb-action-icon>\n}\n";

